package com.chronolock.data

/**
 * A colour palette for the whole app. [name] is persisted, so ids stay stable even when colours change.
 * Built-in palettes follow open-source schemes (Flexoki, Nord, Everforest, Rosé Pine). Catalog palettes
 * (trend, pastel, gradient) are generated by [ThemeCatalog]; every text pairing is nudged to WCAG AA
 * (see ThemePaletteTest).
 */
class AppTheme(
    val name: String,
    /** Translatable words that make up the title, e.g. ["파스텔", "민트"]; each is passed through tr(). */
    val label: List<String>,
    val description: String,
    val isDark: Boolean,
    val background: Long,
    val surface: Long,
    val primary: Long,
    val onPrimary: Long,
    val text: Long,
    val muted: Long,
    /** Bottom colour of a top-to-bottom background gradient, or null for a flat background. */
    val gradientEnd: Long? = null,
    /** Catalog palettes are reserved for a future paid tier. Selection is not gated yet. */
    val premium: Boolean = false,
    /** Colours between [background] and [gradientEnd], top to bottom, for a many-colour page such as a rainbow. */
    val stops: List<Long> = emptyList(),
    /** The page gradient slowly flows instead of standing still. */
    val live: Boolean = false,
) {
    val title: String get() = label.joinToString(" ")
    /** The words shown on a picker tile: everything after the family word, or the whole label for built-ins. */
    val shortLabel: List<String> get() = if (label.size > 1) label.drop(1) else label
    /** Every page colour top to bottom; text is readable on each. */
    val pageColors: List<Long> get() = listOf(background) + stops + listOfNotNull(gradientEnd)

    fun copy(label: List<String> = this.label, premium: Boolean = this.premium): AppTheme =
        AppTheme(name, label, description, isDark, background, surface, primary, onPrimary, text, muted, gradientEnd, premium, stops, live)
    override fun equals(other: Any?) = other is AppTheme && other.name == name
    override fun hashCode() = name.hashCode()
    override fun toString() = name

    companion object {
        val DARK = AppTheme("DARK", listOf("먹"), "따뜻한 먹색 바탕과 주황 포인트", true,
            0xFF100F0F, 0xFF1C1B1A, 0xFFDA702C, 0xFF100F0F, 0xFFCECDC3, 0xFF878580)
        val LIGHT = AppTheme("LIGHT", listOf("종이"), "미색 종이 바탕과 잉크 블루", false,
            0xFFF2F0E5, 0xFFFFFCF0, 0xFF205EA6, 0xFFFFFCF0, 0xFF100F0F, 0xFF6A6964)
        val OCEAN = AppTheme("OCEAN", listOf("북극"), "차가운 슬레이트와 서리 블루", true,
            0xFF2E3440, 0xFF3B4252, 0xFF88C0D0, 0xFF2E3440, 0xFFECEFF4, 0xFFAEB6C4)
        val FOREST = AppTheme("FOREST", listOf("숲"), "어두운 이끼색과 세이지 그린", true,
            0xFF2D353B, 0xFF343F44, 0xFFA7C080, 0xFF2D353B, 0xFFD3C6AA, 0xFFA3AEA5)
        val LAVENDER = AppTheme("LAVENDER", listOf("새벽"), "따뜻한 새벽빛 바탕과 보랏빛 포인트", false,
            0xFFFAF4ED, 0xFFFFFAF3, 0xFF6E5A8C, 0xFFFFFAF3, 0xFF575279, 0xFF6E6A86)

        val builtIn: List<AppTheme> = listOf(DARK, LIGHT, OCEAN, FOREST, LAVENDER)

        /** Every selectable palette, built-ins first. */
        fun values(): List<AppTheme> = builtIn + ThemeCatalog.all

        /** A stored name: a listed palette, a custom one rebuilt from its colour and effect, or [DARK]. */
        fun fromStored(value: String?): AppTheme = ThemeCatalog.resolve(value).let { name ->
            values().firstOrNull { it.name == name }
                ?: ThemeCatalog.parseCustom(name)?.let { (rgb, effects) -> ThemeCatalog.custom(rgb, effects) } ?: DARK
        }
    }
}
